/**
 * Brand gradients — composed from color tokens (no raw hex).
 * Source of truth: ATOM Brand System "Colores" — the Violet→Orange gradient is
 * the most expressive brand element: AI (Violet) producing tangible results
 * (Orange).
 *
 * ALLOWED: hero headline keywords (.text-gradient) and section backgrounds (.bg-*).
 * FORBIDDEN: buttons and CTAs (use .button--primary/--secondary from the button
 * component — buttons are NEVER gradient), icons, chips, and any small element.
 * White stays the page base (humanity); dark backgrounds are AI-themed sections only.
 */

:root {
  --gradient-brand: linear-gradient(135deg, var(--color-violet-600) 0%, var(--brand) 100%);
  --gradient-brand-soft: linear-gradient(135deg, var(--color-violet-50) 0%, #ffffff 60%, var(--color-orange-50) 100%);
  --gradient-dark-glow:
    radial-gradient(60% 80% at 85% 20%, color-mix(in srgb, var(--color-violet-600) 18%, transparent) 0%, transparent 70%),
    radial-gradient(50% 70% at 10% 90%, color-mix(in srgb, var(--brand) 14%, transparent) 0%, transparent 70%),
    linear-gradient(135deg, var(--color-zinc-950) 0%, var(--color-zinc-900) 100%);
}

/* Keyword/headline emphasis. Brand rules: hero headlines only, max 2 highlight
   colors per title, "Atom" stays orange (never let the violet end land on it). */
.text-gradient {
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/**
 * Section background variants for layouts (bgStyle slot in the MCP catalog).
 * Dark variants set a light foreground so sections meet WCAG AA out of the box.
 * Never pure black (brand rule) — dark base is zinc-900/950.
 *
 * USAGE RULE: white is the page base (humanity). .bg-dark / .bg-dark-glow are
 * EXCLUSIVELY for sections about AI (agents, automation) — 0-2 per page, never
 * the whole page. These classes go on <section>, never on body or buttons.
 */

.bg-gradient-brand {
  background: var(--gradient-brand);
  color: var(--color-zinc-50);
}

.bg-gradient-soft {
  background: var(--gradient-brand-soft);
}

.bg-dark {
  background-color: var(--color-zinc-900);
  color: var(--color-zinc-50);
}

.bg-dark-glow {
  background: var(--gradient-dark-glow);
  color: var(--color-zinc-50);
}

.bg-violet-soft {
  background-color: var(--color-violet-50);
}
